code=worker+'''\nconst rtOriginalPost=self.postMessage.bind(self);self.postMessage=(packet,...args)=>{if(packet.ok&&packet.result?.outboxPending!==undefined)setTimeout(()=>rtOriginalPost(packet,...args),120);else rtOriginalPost(packet,...args);};'''
hook='''window.rtLife={fixture:()=>{seed(42);paused=true;for(let i=0;i<19;i++)tick();pendingEvent=null;active='';return archivePayload();},day:()=>G.day,hide:value=>{Object.defineProperty(document,'hidden',{configurable:true,get:()=>value});document.dispatchEvent(new Event('visibilitychange'));},stored:()=>readSaveEnvelope(localStorage.getItem('townledger-v6'))};\n'''
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);p=b.new_page();errors=[];p.on('pageerror',lambda e:errors.append(str(e)));p.route('http://rt-life.test/',lambda r:r.fulfill(body=html,content_type='text/html'));p.goto('http://rt-life.test/');p.add_script_tag(content=source.replace('// SOURCE: 99-instrumentation.js',bridge+hook+'// SOURCE: 99-instrumentation.js'));archive=p.evaluate('rtLife.fixture()');p.evaluate('''async a=>window.real=await __workerRealView.enable(a.code,a.archive,{realtime:true,startPaused:true,initializeAuthority:async ask=>{const r=await ask({type:'initialize-command-owner'});if(!r.ordinaryDayReady)throw Error('Owner unavailable');}})''',{'code':code,'archive':archive});p.locator('#speedRange').focus();p.locator('#speedRange').press('Home');p.wait_for_function('real.realtimeStatus().requested===1');p.evaluate('real.settleRealtime()');p.locator('#speed').click();p.wait_for_function('real.realtimeStatus().requested===2');p.evaluate('real.settleRealtime()');p.evaluate('real.setRealtimeSpeed(64)');p.evaluate('real.settleSaves()');p.evaluate('real.setRealtimePaused(false)');p.wait_for_timeout(250)
 # Queue a real paid action behind an admitted day; pending state must be immediate.
 p.evaluate('''()=>{window.firstPaid=real.command({type:'panel-control',control:'toggleDevelopment'});window.secondPaid=real.command({type:'panel-control',control:'toggleDevelopment'}).then(()=>false,e=>e.message);return true;}''');assert p.locator('#gameRoot').get_attribute('aria-busy')=='true';assert p.evaluate('secondPaid');first=p.evaluate('firstPaid');assert first['paid']['committed'];p.evaluate('real.setRealtimePaused(true)');p.evaluate('real.settleRealtime()');paused=p.evaluate('real.realtimeStatus()');p.wait_for_timeout(250);assert p.evaluate('real.realtimeStatus().committedDay')==paused['committedDay'];assert paused['owedDays']>0
 # A real modal freezes admission and a real defer settles it before resuming.
 p.evaluate('real.command({type:"convene"})');p.wait_for_function('document.querySelector("#eventDialog").style.display==="flex"');p.evaluate('real.setRealtimePaused(false)');modal=p.evaluate('real.realtimeStatus()');p.wait_for_timeout(250);assert p.evaluate('real.realtimeStatus().committedDay')==modal['committedDay'];assert modal['reason']=='review';p.locator('#eventDefer').click();p.wait_for_function('document.querySelector("#eventDialog").style.display==="none"');p.wait_for_timeout(250)
 # Synthetic visibility signal exercises page integration; not Android lifecycle acceptance.
 p.evaluate('rtLife.hide(true)');p.evaluate('real.settleRealtime()');hidden=p.evaluate('real.realtimeStatus()');p.wait_for_timeout(250);assert p.evaluate('real.realtimeStatus().committedDay')==hidden['committedDay'];assert hidden['reason']=='suspended';p.evaluate('rtLife.hide(false)');p.wait_for_timeout(200);assert p.evaluate('__townArchive.suspend()') is True;p.evaluate('real.settleRealtime()');suspended=p.evaluate('real.realtimeStatus()');p.wait_for_timeout(200);assert p.evaluate('real.realtimeStatus().committedDay')==suspended['committedDay'];assert suspended['reason']=='suspended';p.evaluate('__townArchive.resume()');p.wait_for_timeout(200);p.evaluate('real.setRealtimePaused(true)');p.evaluate('real.settleRealtime()');p.evaluate('real.settleSaves()');saved=p.evaluate('real.command({type:"export"})');p.evaluate('real.command({type:"clock-speed",value:16})');p.evaluate('real.settleSaves()');saved=p.evaluate('real.command({type:"export"})');assert json.loads(saved['archive'])==saved['model'];assert json.loads(p.evaluate('rtLife.stored()')['payload'])==saved['model'];assert not p.evaluate('real.recoveryStatus().faulted');assert not errors,errors
 Path('experimental/worker/realtime-lifecycle-proof.json').write_text(json.dumps({'productionEnabled':False,'sourceSha256':hashlib.sha256(source.encode()).hexdigest(),'workerSha256':hashlib.sha256(worker.encode()).hexdigest(),'bridgeSha256':hashlib.sha256(bridge.encode()).hexdigest(),'delayedReplyMs':120,'paidQueuedImmediatePendingAndDuplicateRefusal':True,'pausePreservesBacklogWithoutDraining':True,'realCouncilReviewStopsClockAndDeferResumes':True,'syntheticVisibilityStopsAdmission':True,'originalSaveOwnerFullCommittedArchiveMatches':True,'actualJavascriptNativeSuspendResumeStopsAdmission':True,'nativeLifecycleAcceptance':False,'pageErrors':errors},indent=2)+'\n');print('PASS delayed-day paid queue, duplicate refusal, pause/backlog, council, synthetic visibility and committed save');b.close()
